document.addEventListener("DOMContentLoaded",()=>{let e=new Date;const u=document.querySelector('input[type="date"]');u.value=e.toISOString().split("T")[0],console.log(e.toISOString().split("T")[0]);const n=document.getElementById("Progress");n&&n.addEventListener("submit",async i=>{i.preventDefault();const o=document.getElementById("InputActivities"),l=document.getElementById("Tanggal"),a=document.getElementById("InputVolume"),r=document.getElementById("Unit"),s=document.getElementById("InputCompletion"),c={rak:o.value,tgl:l.value,volume:a.value,satuan:r.value,waktu:s.value};try{const t=await fetch("/api/progress",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(c)});if(!t.ok)throw new Error(`HTTP error! status: ${t.status}`);Swal.fire({icon:"success",title:"Succeed",text:"Kegiatan berhasil disimpan",showConfirmButton:!1,timer:2e3}),o.value="",a.value="",s.value=""}catch{}})});
